head.b:skin:
/* ===== RESET & BASE STYLES ===== */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Be Vietnam Pro', -apple-system, sans-serif;
  background-color: #f7f9fc;
  color: #2c3e50;
  line-height: 1.6;
}
a { color: #8b0000; text-decoration: none; transition: all 0.2s ease; }
a:hover { color: #c0392b; }

/* ===== HEADER & NAVIGATION ===== */
.kybien-navbar {
  background: #8b0000;
  color: #ffffff;
  padding: 12px 20px;
  box-shadow: 0 4px 12px rgba(139, 0, 0, 0.15);
  position: sticky;
  top: 0;
  z-index: 1000;
}
.nav-container {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.brand-logo {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.brand-logo span { color: #f1c40f; }
.nav-links { display: flex; gap: 20px; list-style: none; align-items: center; }
.nav-links a { color: #ffffff; font-weight: 600; font-size: 0.95rem; }
.nav-links a:hover { color: #f1c40f; }

/* ===== MAIN LAYOUT ===== */
.main-wrapper {
  max-width: 1100px;
  margin: 30px auto;
  padding: 0 20px;
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 30px;
}

/* ===== POST & ARTICLE STYLES ===== */
.content-area { background: #fff; padding: 30px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
.post-title { font-size: 1.8rem; font-weight: 700; color: #1a252f; margin-bottom: 15px; line-height: 1.3; }

/* Replay Viewer Component */
.kybien-viewer-container {
  background: #faf6f0;
  border: 2px solid #e2d7c5;
  border-radius: 10px;
  padding: 20px;
  margin: 20px 0;
  text-align: center;
}
.viewer-controls button {
  background: #8b0000;
  color: #fff;
  border: none;
  padding: 8px 16px;
  margin: 4px;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

/* Sa truong commentary article */
.sa-truong-article {
  font-family: 'Merriweather', serif;
  background: #fdfaf6;
  padding: 20px;
  border-left: 4px solid #8b0000;
  border-radius: 4px;
  margin-top: 25px;
}

/* ===== SIDEBAR ===== */
.sidebar { display: flex; flex-direction: column; gap: 20px; }
.widget-box { background: #fff; padding: 20px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.05); }
.widget-title { font-size: 1.1rem; font-weight: 700; color: #8b0000; border-bottom: 2px solid #f0e6d2; padding-bottom: 8px; margin-bottom: 15px; }

.kybien-auth-buttons .btn-login {
  background: #f1c40f;
  color: #8b0000;
  padding: 8px 16px;
  border-radius: 20px;
  font-weight: 700;
  display: inline-block;
}
